from pathlib import Path
import json,hashlib,zipfile,html,sys,platform,importlib.metadata,re
R=Path(__file__).resolve().parents[1]
# Remove generated bytecode and empty scratch folders from engineering delivery.
import shutil
for p in list(R.rglob('__pycache__')):shutil.rmtree(p)
for rel in ['simulation/results','simulation','sources/vendor_notes']:
 p=R/rel
 if p.exists() and not list(p.iterdir()):p.rmdir()
versions={'python':sys.version,'platform':platform.platform(),'native_kicad':'NOT_INSTALLED','ngspice':'NOT_INSTALLED','freecad':'NOT_INSTALLED','revision':'R52-G4-E02-D01'}
for k in ['cadquery','numpy','shapely','reportlab']:
 try:versions[k]=importlib.metadata.version(k)
 except Exception:versions[k]='UNKNOWN'
(R/'validation/results/environment.json').write_text(json.dumps(versions,indent=2))
links=[('设计说明（10页）','docs/ZL80_G4_PCB与结构联动设计说明.pdf'),('PCB与装配图册（9页）','drawings/ZL80_G4_PCB与装配审查图册.pdf'),('四板原理图（4页）','docs/ZL80_G4_四板原理图审查.pdf'),('接口与验证工作簿（12表）','engineering/ZL80_G4_接口变更与板卡验证.xlsx'),('去罩机械回装STEP','cad/assemblies/ZL80_G4_Core_Integration.step'),('含外壳回装STEP','cad/assemblies/ZL80_G4_G3_Integration.step'),('四板安装STEP','cad/assemblies/ZL80_G4_4Boards_Installed.step'),('制造门禁','validation/results/release_gate.json')]
for bid in ['B06','B07','B08','B01']:links += [(bid+' KiCad工程',f'electronics/projects/{bid}/{bid}_G4.kicad_pro'),(bid+' 已布铜线候选',f'electronics/projects/{bid}/{bid}_G4.kicad_pcb')]
for title,rel in links:assert (R/rel).exists(),rel
style='''body{margin:0;background:#edf2f6;color:#183047;font:16px/1.65 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1120px;margin:38px auto;padding:0 24px}header{background:#15334d;color:white;padding:34px;border-radius:12px}h1{margin:0;font-size:34px}h2{margin-top:32px}.badge{background:#ffe6df;color:#992b15;padding:15px 22px;border-radius:8px;margin:18px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(245px,1fr));gap:14px}a.card{display:block;background:white;padding:20px;text-decoration:none;color:#163f60;border-radius:8px;border:1px solid #d0dbe4}small{display:block;color:#697e8d;font-size:12px;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;background:white}td,th{padding:12px;border-bottom:1px solid #d7e0e7;text-align:left}th{background:#dbe7ef}code{background:#dde7ed;padding:4px}footer{padding:24px;color:#596d7a}'''
htmltxt='<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZL80 G4 工程交付</title><style>'+style+'</style><main><header><h1>ZL80 · G4</h1><p>PCB与结构联动首批工程交付 / R52-G4-E02-D01 / 2026-11-16</p></header><div class="badge"><b>制造状态 BLOCKED</b> — 三块小板实际铜线候选；B01关键网部分布线；B02—B05未闭合。原生ERC/DRC、台架及制造审批尚未执行。</div><h2>先阅读与下载</h2><div class="grid">'
for title,rel in links:htmltxt+=f'<a class="card" href="{html.escape(rel)}">{html.escape(title)}<small>{html.escape(rel)}</small></a>'
htmltxt+='</div><h2>本轮完成度</h2><table><tr><th>板卡</th><th>铜线段</th><th>过孔</th><th>最少未连接</th><th>边界</th></tr>'
for r in json.loads((R/'validation/results/copper_audit.json').read_text()):htmltxt+=f'<tr><td>{r["board"]}</td><td>{r["segments"]}</td><td>{r["vias"]}</td><td>{r["unconnected_min_links"]}</td><td>自编几何/网络回读；不是KiCad原生DRC</td></tr>'
htmltxt+='</table><h2>启动</h2><p>完整解压后，用KiCad打开B06_G4.kicad_pro。先核对库、封装、方向，再填铜并执行原生ERC/DRC。所有假设接口须经审核后才接入实物。</p><p><a href="README_先读.md">中文操作说明</a> · <a href="engineering/change_register.csv">变更单</a> · <a href="engineering/open_issues.csv">待关闭问题</a> · <a href="validation/test_matrix.csv">12项验证协议</a></p><footer>本包保留来源、脚本、文件校验和以及未完成状态。不要用改状态替代真实验证。</footer></main></html>'
(R/'START_HERE.html').write_text(htmltxt,encoding='utf8')
files=[p for p in R.rglob('*') if p.is_file() and p.name not in ['MANIFEST_SHA256.json','PACKAGE_SUMMARY.json']]
manifest={str(p.relative_to(R)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(files)}
(R/'MANIFEST_SHA256.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
from collections import Counter
summary={'revision':'R52-G4-E02-D01','files_excluding_self':len(files)+1,'extension_counts':dict(Counter(p.suffix.lower() for p in files)),'release':'BLOCKED','zip_members_prefix':R.name}
(R/'PACKAGE_SUMMARY.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2))
def archive(path,selector):
 with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED,compresslevel=8) as z:
  for p in sorted(R.rglob('*')):
   if p.is_file() and '__pycache__' not in str(p) and selector(p.relative_to(R)):z.write(p,str(Path(R.name)/p.relative_to(R)))
 with zipfile.ZipFile(path) as z:assert z.testzip() is None;print(path.name,len(z.namelist()),path.stat().st_size)
archive(R.parent/'ZL80_R52_G4_PCB_MCAD_Delivery.zip',lambda p:True)
archive(R.parent/'ZL80_G4_KiCad_4Boards.zip',lambda p:p.parts[0] in ['electronics'] and 'downstream_R51_UNCLOSED' not in p.parts or str(p) in ['README_先读.md','engineering/board_status.csv','engineering/change_register.csv'])
archive(R.parent/'ZL80_G4_CAD_Integration.zip',lambda p:p.parts[0]=='cad' or str(p) in ['README_先读.md','engineering/board_transforms.json','engineering/photodiode_coordinates.csv','engineering/connector_pin_world.csv','validation/results/mcad_audit.json'])
print(json.dumps(summary,ensure_ascii=False,indent=2))
